import sys
from math import gcd


def best_divisor(g, r):
    """Largest divisor of g that does not exceed r."""
    if g <= r:
        return g
    best = 1
    d = 1
    while d * d <= g:
        if g % d == 0:
            if d <= r:
                best = max(best, d)
            if g // d <= r:
                best = max(best, g // d)
        d += 1
    return best


def main():
    data = sys.stdin.buffer.read().split()
    n, r = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    pre = [0] * (n + 1)
    for i, x in enumerate(a):
        pre[i + 1] = gcd(pre[i], x)
    suf = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suf[i] = gcd(suf[i + 1], a[i])
    answer = pre[n]
    cache = {}  # the gcd of "all but one" takes few distinct values
    for i in range(n):
        g = gcd(pre[i], suf[i + 1])
        if g not in cache:
            cache[g] = best_divisor(g, r)
        answer = max(answer, cache[g])
    print(answer)


