import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int bestDivisor(int g, int r) {
        if (g <= r) return g;
        int best = 1;
        for (int d = 1; (long) d * d <= g; d++) {
            if (g % d == 0) {
                if (d <= r) best = Math.max(best, d);
                if (g / d <= r) best = Math.max(best, g / d);
            }
        }
        return best;
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), r = nextInt();
        int[] a = new int[n], pre = new int[n + 1], suf = new int[n + 1];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        for (int i = 0; i < n; i++) pre[i + 1] = gcd(pre[i], a[i]);
        for (int i = n - 1; i >= 0; i--) suf[i] = gcd(suf[i + 1], a[i]);
        int answer = pre[n];
        for (int i = 0; i < n; i++) answer = Math.max(answer, bestDivisor(gcd(pre[i], suf[i + 1]), r));
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

// bestDivisor returns the largest divisor of g that does not exceed r.
func bestDivisor(g, r int) int {
	if g <= r {
		return g
	}
	best := 1
	for d := 1; d*d <= g; d++ {
		if g%d == 0 {
			if d <= r {
				best = max(best, d)
			}
			if g/d <= r {
				best = max(best, g/d)
			}
		}
	}
	return best
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, r := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	pre := make([]int, n+1)
	suf := make([]int, n+1)
	for i := 0; i < n; i++ {
		pre[i+1] = gcd(pre[i], a[i])
	}
	for i := n - 1; i >= 0; i-- {
		suf[i] = gcd(suf[i+1], a[i])
	}
	answer := pre[n]
	for i := 0; i < n; i++ {
		answer = max(answer, bestDivisor(gcd(pre[i], suf[i+1]), r))
	}
	fmt.Println(answer)
}
